const dns = require('dns');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { EventEmitter } = require('events');

class DNSResolverService extends EventEmitter {
  constructor(config) {
    super();
    this.cacheDir = config.cacheDir || '/tmp/dns-cache';
    this.templateDir = config.templateDir || './templates';
    this.maxBatchSize = config.maxBatchSize || 100;
    this.resolveTimeout = config.resolveTimeout || 5000;
    this.outputFormat = config.outputFormat || 'html';
    fs.mkdirSync(this.cacheDir, { recursive: true });
  }

  sanitizeDomain(domain) {
    const cleaned = domain.trim().toLowerCase();
    if (!/^[a-z0-9][a-z0-9\-\.]{0,253}[a-z0-9]$/.test(cleaned)) {
      throw new Error(`Invalid domain: ${cleaned}`);
    }
    if (cleaned.includes('..')) throw new Error('Invalid domain segments');
    return cleaned;
  }

  generateCacheKey(domain, recordType) {
    return crypto.createHash('sha256')
      .update(`${domain}:${recordType}`)
      .digest('hex').slice(0, 16);
  }

  async resolveSingle(domain, recordType = 'A') {
    return new Promise((resolve, reject) => {
      const timeout = setTimeout(() => reject(new Error('Timeout')), this.resolveTimeout);
      dns.resolve(domain, recordType, (err, records) => {
        clearTimeout(timeout);
        if (err) reject(err);
        else resolve({ domain, recordType, records, timestamp: Date.now() });
      });
    });
  }

  async processBatchUpload(uploadBuffer) {
    const content = uploadBuffer.toString('utf-8');
    const lines = content.split(/\r?\n/).filter(l => l.trim().length > 0);

    if (lines.length > this.maxBatchSize) {
      throw new Error(`Batch exceeds maximum size of ${this.maxBatchSize}`);
    }

    const results = [];
    for (const line of lines) {
      const parts = line.split(/\s+/);
      const domain = parts[0];
      const recordType = (parts[1] || 'A').toUpperCase();
      const comment = parts.slice(2).join(' ');

      try {
        const cleanDomain = this.sanitizeDomain(domain);
        const result = await this.resolveSingle(cleanDomain, recordType);
        result.comment = comment;
        results.push(result);
      } catch (err) {
        results.push({ domain, recordType, error: err.message, comment });
      }
    }

    return results;
  }

  formatResultEntry(result) {
    const status = result.error ? 'FAILED' : 'RESOLVED';
    const records = result.records ? result.records.join(', ') : 'N/A';
    const comment = result.comment || '';
    return { status, domain: result.domain, type: result.recordType, records, comment };
  }

  renderTemplate(templateName, context) {
    const templatePath = path.join(this.templateDir, `${templateName}.shtml`);
    let template = fs.readFileSync(templatePath, 'utf-8');

    for (const [key, value] of Object.entries(context)) {
      const placeholder = `{{${key}}}`;
      template = template.replace(new RegExp(placeholder.replace(/[{}]/g, '\\$&'), 'g'), String(value));
    }
    return template;
  }

  buildReportContent(results) {
    const entries = results.map(r => this.formatResultEntry(r));
    let body = '';

    for (const entry of entries) {
      body += this.renderTemplate('row', {
        status: entry.status,
        domain: entry.domain,
        type: entry.type,
        records: entry.records,
        comment: entry.comment
      });
    }
    return body;
  }

  async generateReport(uploadBuffer, reportId) {
    const results = await this.processBatchUpload(uploadBuffer);
    const body = this.buildReportContent(results);

    const reportContent = this.renderTemplate('report', {
      title: 'DNS Resolution Report',
      reportId: reportId,
      generatedAt: new Date().toISOString(),
      body: body,
      totalCount: results.length,
      successCount: results.filter(r => !r.error).length
    });

    const outputPath = path.join(this.cacheDir, `${reportId}.shtml`);
    fs.writeFileSync(outputPath, reportContent);
    this.emit('reportGenerated', { reportId, path: outputPath });
    return outputPath;
  }
}

module.exports = { DNSResolverService };
